SourceCode.Declaration:
/// <summary>
/// One claimable location range of a wall-to-wall counting journal (an aisle or zone), as split
/// by the planner. Returned inside HSMobileOpsJournalSummaryRow.Ranges. An empty list means the
/// journal is claimed whole.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountRangeRow
{
    str rangeId;
    str label;
    str locationFrom;
    str locationTo;
    int lineCount;

}

Method.Source:
[DataMemberAttribute('RangeId')]
public str parmRangeId(str _value = rangeId)
{
    rangeId = _value;
    return rangeId;
}

[DataMemberAttribute('Label')]
public str parmLabel(str _value = label)
{
    label = _value;
    return label;
}

[DataMemberAttribute('LocationFrom')]
public str parmLocationFrom(str _value = locationFrom)
{
    locationFrom = _value;
    return locationFrom;
}

[DataMemberAttribute('LocationTo')]
public str parmLocationTo(str _value = locationTo)
{
    locationTo = _value;
    return locationTo;
}

[DataMemberAttribute('LineCount')]
public int parmLineCount(int _value = lineCount)
{
    lineCount = _value;
    return lineCount;
}
